// queueSettledReviewStep queues the validate-and-promote step for a done
// full-pipeline Change Task whose current heads a disposition settled.
func queueSettledReviewStep(ctx context.Context, db *store.DB, project store.Project, change store.Task, reason string) error {
	if !project.IsWorkspace() {
		plan, err := change.AdmittedPlan()
		if err != nil {
			return admittedPlanFailure(err)
		}
		if plan != nil && plan.Review == "full-pipeline" && taskUsesGreenhouseReviewProvider(change, config.Config{}, "") {
			head, err := taskBranchAuthorHead(ctx, project.Root, change.Branch)
			if err != nil {
				return err
			}
			accepted, err := greenhouseAcceptHeadDisposition(ctx, db, change, head)
			if err != nil || !accepted {
				return err
			}
			signals, err := db.TaskSignals(ctx, change.ID, 1)
			if err != nil {
				return err
			}
			body := fmt.Sprintf("%s The User accepted this exact Greenhouse-reviewed head at the Review cap. Publish it unchanged with `posse publish \"%s\"`, then report done with the PR URL. The PR description must preserve the accepted findings and User quote.", reason, change.Title)
			if len(signals) > 0 {
				_, _, err = db.QueueMessageOnceAfter(ctx, change.ID, body, true, signals[0].At-1)
			}
			return err
		}
	}
	targets, err := changeCandidateTargets(ctx, db, project, change)
	if err != nil {
		var failure *axi.Error
		if errors.As(err, &failure) {
			return nil
		}
		return err
	}
	step, err := reviewNextStep(ctx, db, project, change, targets, reason)
	if err != nil || step == nil {
		return err
	}
	step.Summary = fmt.Sprintf("%s: %s; queued the Worker to validate and promote candidate %s", change.Title, reason, strings.Join(stepHeads(step), ", "))
	return db.QueueReviewNextStep(ctx, project.ID, *step)
}

// settleReviewDisposition runs after `review dispose`: when the last round
// requested changes on the current heads and no blocking finding remains, the
// heads count as reviewed and the Worker gets the same next step as a pass.
func settleReviewDisposition(ctx context.Context, db *store.DB, project store.Project, change store.Task, action string) error {
	if change.Type != "change" || change.State != store.StateDone {
		return nil
	}
	plan, err := change.AdmittedPlan()
	if err != nil || plan == nil || plan.Review != "full-pipeline" {
		return nil
	}
	findings, err := db.ReviewFindingsForTask(ctx, change.ID)
	if err != nil {
		return err
	}
	for _, finding := range findings {
		if reviewFindingBlocks(finding, plan) {
			return nil
		}
	}
	targets, err := changeCandidateTargets(ctx, db, project, change)
	if err != nil {
		return nil
	}
	verdicts, err := db.ReviewVerdictsFor(ctx, change.ID)
	if err != nil || len(verdicts) == 0 {
		return err
	}
	last := verdicts[0]
	if last.Verdict != store.ReviewChangesRequested || !slices.Equal(last.Targets, targets) {
		return nil
	}
	if evidence, err := db.ReviewEvidenceFor(ctx, change.ID, targets); err != nil {
		return err
	} else if !evidence.Complete {
		heads := make([]string, len(targets))
		for i, target := range targets {
			heads[i] = target.Commit
		}
		if err := db.RecordReviewHeadDisposition(ctx, change.ID, heads, "no blocking finding remains after review dispose "+action); err != nil {
			return err
		}
	}
	return queueSettledReviewStep(ctx, db, project, change, "Review disposition "+action+" left no blocking finding on "+taskIDString(change.Seq))
}

// RecordReviewDisposition binds an authorized acceptance to exact heads,
// one per changed repository, and appends its finding-state events atomically.
func (db *DB) RecordReviewDisposition(ctx context.Context, taskID, decisionID int64, heads []string, quote, blockAt, actor, reason string) error {
	if taskID < 1 || len(heads) == 0 || (actor == "user" && strings.TrimSpace(quote) == "") || (actor == "lead" && strings.TrimSpace(reason) == "") || !oneOf(actor, "user", "lead") || !oneOf(blockAt, "P0", "P1", "P2") {
		return fmt.Errorf("invalid Review disposition")
	}
	for _, head := range heads {
		if !validValidationSHA(head) {
			return fmt.Errorf("invalid Review disposition")
		}
	}
	tx, err := db.beginTxWithRetry(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if err := insertReviewDispositionsTx(ctx, tx, taskID, decisionID, heads, quote, actor, reason); err != nil {
		return err
	}
	rows, err := tx.QueryContext(ctx, `SELECT f.id,f.seq,f.severity,f.origin,f.in_scope,f.state FROM review_findings f WHERE f.ship_task_id=? ORDER BY f.seq`, taskID)
	if err != nil {
		return err
	}
	type finding struct {
		id                      int64
		seq                     int
		severity, origin, state string
		inScope                 bool
	}
	var findings []finding
	for rows.Next() {
		var value finding
		var inScope int
		if err := rows.Scan(&value.id, &value.seq, &value.severity, &value.origin, &inScope, &value.state); err != nil {
			rows.Close()
			return err
		}
		value.inScope = inScope == 1
		findings = append(findings, value)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}
	threshold := map[string]int{"P0": 0, "P1": 1, "P2": 2}[blockAt]
	for _, value := range findings {
		if !oneOf(value.state, "open", "fix_claimed", "unverified", "disputed", "regressed") {
			continue
		}
		state, event := "deferred", "deferred"
		if value.origin == "introduced" && value.inScope && (value.severity == "unclassified" || map[string]int{"P0": 0, "P1": 1, "P2": 2, "P3": 3}[value.severity] <= threshold) {
			state, event = "accepted", "accepted"
		}
		if _, err := tx.ExecContext(ctx, `UPDATE review_findings SET state=? WHERE id=? AND ship_task_id=?`, state, value.id, taskID); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `INSERT INTO review_finding_events(finding_id,round,event,actor,note,user_quote,at) VALUES(?,0,?,?,?,?,?)`, value.id, event, actor, "accepted at review cap", quote, time.Now().UnixMilli()); err != nil {
			return err
		}
	}
	if err := tx.Commit(); err != nil {
		return err
	}
	return db.PersistTask(ctx, taskID)
}

func insertReviewDispositionsTx(ctx context.Context, tx *writeTx, taskID, decisionID int64, heads []string, quote, actor, reason string) error {
	for _, head := range heads {
		var existing bool
		if err := tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM review_dispositions WHERE ship_task_id=? AND head_sha=?)`, taskID, head).Scan(&existing); err != nil {
			return err
		}
		if !existing {
			if _, err := tx.ExecContext(ctx, `INSERT INTO review_dispositions(ship_task_id,head_sha,decision_id,user_quote,at,actor,reason) VALUES(?,?,?,?,?,?,?)`, taskID, head, nullableDecisionID(decisionID), quote, time.Now().UnixMilli(), actor, reason); err != nil {
				return err
			}
		}
	}
	return nil
}

// RecordReviewHeadDisposition binds the current heads to a disposition that
// left no blocking finding, without touching any finding. The next step needs
// no User quote because no blocking finding was accepted.
func (db *DB) RecordReviewHeadDisposition(ctx context.Context, taskID int64, heads []string, note string) error {
	tx, err := db.beginTxWithRetry(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if err := insertReviewDispositionsTx(ctx, tx, taskID, 0, heads, note, "system", ""); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return err
	}
	return db.PersistTask(ctx, taskID)
}

