		return err
	}
	return ctx.Print(axi.Object{{Key: "task", Value: taskIDString(change.Seq)}, {Key: "action", Value: action}, {Key: "findings", Value: appliedFindings}, {Key: "patterns", Value: len(patterns)}, {Key: "state", Value: "recorded"}})
}

